import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { toast } from 'react-toastify';
import { User, Mail, Lock, Eye, EyeOff, Facebook, Twitter } from 'lucide-react';

const Register = () => {
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (formData.password !== formData.confirmPassword) {
      toast.error('Passwords do not match');
      return;
    }

    if (formData.password.length < 6) {
      toast.error('Password must be at least 6 characters');
      return;
    }

    setLoading(true);

    const result = await register(formData.username, formData.email, formData.password);
    
    if (result.success) {
      toast.success('Registration successful!');
    } else {
      toast.error(result.error);
    }
    
    setLoading(false);
  };

  return (
    <div className="auth-container flex">
      {/* Left Side - Illustration */}
      <div className="hidden lg:flex lg:w-1/2 auth-illustration items-center justify-center p-12">
        <div className="max-w-md">
          {/* Office Workspace Illustration */}
          <div className="office-illustration">
            {/* Wall with shelves */}
            <div className="office-wall">
              {/* Top shelf */}
              <div className="office-shelf top-4 left-8 w-32"></div>
              <div className="office-shelf-item top-2 left-10 w-6 h-6 bg-gray-400"></div>
              <div className="office-shelf-item top-2 left-18 w-6 h-6 bg-gray-400"></div>
              <div className="office-shelf-item top-2 left-26 w-4 h-4 bg-green-400 rounded-full"></div>
              
              {/* Bottom shelf */}
              <div className="office-shelf top-12 left-8 w-32"></div>
              <div className="office-shelf-item top-10 left-10 w-4 h-4 bg-blue-400"></div>
              <div className="office-shelf-item top-10 left-16 w-4 h-4 bg-blue-400"></div>
              <div className="office-shelf-item top-10 left-22 w-4 h-4 bg-blue-400"></div>
              <div className="office-shelf-item top-10 left-28 w-4 h-4 bg-yellow-400"></div>
            </div>
            
            {/* Desk */}
            <div className="office-desk">
              {/* Desk base */}
              <div className="office-desk-base"></div>
              
              {/* Plant on left */}
              <div className="office-plant top-4 left-4 w-6 h-8 bg-purple-600"></div>
              <div className="office-plant top-2 left-5 w-4 h-4 bg-green-400"></div>
              
              {/* Computer monitor */}
              <div className="office-monitor">
                <div className="office-monitor-screen">
                  <div className="absolute top-1 left-1 w-12 h-1 bg-blue-500 rounded"></div>
                  <div className="absolute top-3 left-1 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-3 left-3 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-3 left-5 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-3 left-7 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-5 left-1 w-8 h-1 bg-gray-300 rounded"></div>
                  <div className="absolute top-6 left-1 w-6 h-1 bg-gray-300 rounded"></div>
                </div>
              </div>
              
              {/* Tablet/Clipboard */}
              <div className="absolute top-8 left-32 w-8 h-10 bg-white rounded border-2 border-gray-300">
                <div className="absolute top-1 left-1 w-6 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-2 left-1 w-6 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-3 left-1 w-6 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-4 left-1 w-2 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-4 left-4 w-2 h-1 bg-gray-400 rounded"></div>
              </div>
              
              {/* Filing cabinet */}
              <div className="absolute top-12 left-44 w-8 h-16 bg-gray-400 rounded">
                <div className="absolute top-2 left-1 w-6 h-2 bg-gray-500 rounded"></div>
                <div className="absolute top-5 left-1 w-6 h-2 bg-gray-500 rounded"></div>
                <div className="absolute top-8 left-1 w-6 h-2 bg-gray-500 rounded"></div>
                <div className="absolute top-11 left-1 w-6 h-2 bg-gray-500 rounded"></div>
              </div>
              
              {/* Person */}
              <div className="office-person">
                {/* Chair */}
                <div className="w-6 h-8 bg-purple-600 rounded"></div>
                {/* Person */}
                <div className="absolute -top-4 left-2 w-4 h-4 bg-gray-300 rounded-full"></div>
                <div className="absolute -top-2 left-1 w-6 h-6 bg-blue-800 rounded"></div>
                <div className="absolute top-2 left-1 w-6 h-4 bg-gray-600 rounded"></div>
              </div>
              
              {/* Plant on right */}
              <div className="office-plant top-4 right-4 w-8 h-12 bg-gray-400">
                <div className="office-plant top-0 left-1 w-6 h-6 bg-purple-500"></div>
                <div className="office-plant top-2 left-0 w-6 h-6 bg-purple-500"></div>
                <div className="office-plant top-4 left-2 w-6 h-6 bg-purple-500"></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Right Side - Register Form */}
      <div className="w-full lg:w-1/2 auth-form-container flex items-center justify-center p-12">
        <div className="w-full max-w-md">
          <div className="text-center mb-8">
            <h2 className="auth-title text-4xl mb-4">Sign Up</h2>
            <p className="auth-subtitle text-lg">
              Lorem ipsum dolor sit amet elit. Sapiente sit aut eos consectetur adipisicing.
            </p>
          </div>

          <form className="space-y-6" onSubmit={handleSubmit}>
            <div>
              <input
                id="username"
                name="username"
                type="text"
                required
                className="auth-input w-full px-4 py-4"
                placeholder="Username"
                value={formData.username}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <input
                id="email"
                name="email"
                type="email"
                required
                className="auth-input w-full px-4 py-4"
                placeholder="Email"
                value={formData.email}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <input
                id="password"
                name="password"
                type={showPassword ? 'text' : 'password'}
                required
                className="auth-input w-full px-4 py-4"
                placeholder="Password"
                value={formData.password}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <input
                id="confirmPassword"
                name="confirmPassword"
                type={showConfirmPassword ? 'text' : 'password'}
                required
                className="auth-input w-full px-4 py-4"
                placeholder="Confirm Password"
                value={formData.confirmPassword}
                onChange={handleChange}
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="auth-button w-full py-4 px-6 text-white disabled:opacity-50"
            >
              {loading ? 'Creating account...' : 'Sign Up'}
            </button>

            <div className="auth-divider">
              <span>– or sign up with –</span>
            </div>

            <div className="flex justify-center space-x-4">
              <button
                type="button"
                className="social-button facebook"
              >
                <Facebook className="w-6 h-6" />
              </button>
              <button
                type="button"
                className="social-button twitter"
              >
                <Twitter className="w-6 h-6" />
              </button>
              <button
                type="button"
                className="social-button google"
              >
                <span className="text-lg font-bold">G</span>
              </button>
            </div>

            <div className="text-center">
              <p className="text-gray-600">
                Already have an account?{' '}
                <Link
                  to="/login"
                  className="auth-link"
                >
                  Sign in here
                </Link>
              </p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Register;
